ALTER FUNCTION public.profile_input_guard() SECURITY DEFINER;
REVOKE ALL ON FUNCTION public.profile_input_guard() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.save_ai_workout(_student_id uuid,_plan jsonb,_model text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid;v uuid;s uuid;session jsonb;exercise jsonb;i int:=0;j int; n int;BEGIN IF NOT public.is_trainer_of(_student_id) THEN RAISE EXCEPTION 'Acesso negado';END IF;PERFORM 1 FROM public.students WHERE id=_student_id AND data_consent_at IS NOT NULL FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Consentimento necessário';END IF;IF EXISTS(SELECT 1 FROM public.workout_versions WHERE student_id=_student_id AND status='pendente') THEN RAISE EXCEPTION 'Já existe um treino pendente';END IF;IF jsonb_array_length(_plan->'sessions') NOT BETWEEN 1 AND 7 THEN RAISE EXCEPTION 'Sessões inválidas';END IF;SELECT id INTO w FROM public.workouts WHERE student_id=_student_id ORDER BY created_at LIMIT 1;IF w IS NULL THEN INSERT INTO public.workouts(student_id,title,created_by) VALUES(_student_id,left(_plan->>'title',120),auth.uid()) RETURNING id INTO w;END IF;SELECT coalesce(max(version_number),0)+1 INTO n FROM public.workout_versions WHERE workout_id=w;INSERT INTO public.workout_versions(workout_id,student_id,version_number,status,source,ai_model,summary,weekly_split,progression,cautions,requires_clearance,created_by) VALUES(w,_student_id,n,'pendente','ia',_model,_plan->>'summary',_plan->>'weekly_split',_plan->>'progression',_plan->>'cautions',coalesce((_plan->>'requires_clearance')::boolean,false),auth.uid()) RETURNING id INTO v;FOR session IN SELECT value FROM jsonb_array_elements(_plan->'sessions') LOOP IF jsonb_array_length(session->'exercises') NOT BETWEEN 4 AND 8 THEN RAISE EXCEPTION 'Cada sessão precisa ter entre 4 e 8 exercícios';END IF;INSERT INTO public.workout_sessions(version_id,position,name,day_of_week,muscle_groups,notes) VALUES(v,i,session->>'name',session->>'day_of_week',session->>'muscle_groups',session->>'notes') RETURNING id INTO s;j:=0;FOR exercise IN SELECT value FROM jsonb_array_elements(session->'exercises') LOOP INSERT INTO public.workout_exercises(version_id,session_id,position,name,muscle_group,sets,reps,rest_seconds,instructions,alternatives,notes) VALUES(v,s,j,exercise->>'name',exercise->>'muscle_group',(exercise->>'sets')::int,exercise->>'reps',(exercise->>'rest_seconds')::int,exercise->>'instructions',exercise->>'alternatives',exercise->>'notes');j:=j+1;END LOOP;i:=i+1;END LOOP;INSERT INTO public.workout_reviews(version_id,action,notes,reviewer_id) VALUES(v,'gerado_ia','Proposta gerada por '||_model,auth.uid());PERFORM public.log_audit(_student_id,'treino_gerado_ia','workout_versions',v,jsonb_build_object('modelo',_model));RETURN v;END $$;
REVOKE ALL ON FUNCTION public.save_ai_workout(uuid,jsonb,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_ai_workout(uuid,jsonb,text) TO authenticated;
SELECT cron.schedule('team-oliveira-relationship-notifications','0 11 * * *','SELECT public.relationship_daily_notifications();');
CREATE OR REPLACE FUNCTION public.lead_input_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.email)>255 OR length(NEW.phone)>30 OR length(NEW.objective)>1000 OR length(NEW.notes)>4000 OR length(NEW.source)>150 OR NEW.birth_date>public.today_br() THEN RAISE EXCEPTION 'Revise os dados do interessado';END IF;IF TG_OP='UPDATE' AND NEW.trainer_id<>OLD.trainer_id THEN RAISE EXCEPTION 'O responsável não pode ser alterado';END IF;RETURN NEW;END $$;
CREATE TRIGGER lead_input_validation BEFORE INSERT OR UPDATE ON public.crm_leads FOR EACH ROW EXECUTE FUNCTION public.lead_input_guard();